import{_ as r,c as a,o as i,ah as t}from"./chunks/framework.DaDXF32t.js";const b=JSON.parse('{"title":"Installer probe and header fix design","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/2026-08-02-probe-and-header-fix-design.md","filePath":"superpowers/2026-08-02-probe-and-header-fix-design.md","lastUpdated":1785749755000}'),n={name:"superpowers/2026-08-02-probe-and-header-fix-design.md"};function o(s,e,l,d,c,h){return i(),a("div",null,e[0]||(e[0]=[t('<h1 id="installer-probe-and-header-fix-design" tabindex="-1">Installer probe and header fix design <a class="header-anchor" href="#installer-probe-and-header-fix-design" aria-label="Permalink to “Installer probe and header fix design”">​</a></h1><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to “Problem”">​</a></h2><p>The Windows installer reports that every UV or PyPI source failed its probe even though the same URLs return HTTP 200 from the same machine. The title block is centered as one box, so its shorter lines are not individually centered.</p><h2 id="confirmed-cause" tabindex="-1">Confirmed cause <a class="header-anchor" href="#confirmed-cause" aria-label="Permalink to “Confirmed cause”">​</a></h2><p>Source probes are launched concurrently with <code>std::async</code>. Their first operation is <code>curl_easy_init()</code>, but the installer never calls <code>curl_global_init()</code> before those threads start. libcurl requires global initialization before concurrent use. The current probe also collapses every CURL error and HTTP response into <code>-1</code>, then discards every failed probe; an empty ranking therefore prevents any real download attempt.</p><p>Direct requests with the Windows system proxy explicitly bypassed returned HTTP 200 for representative PyPI, Aliyun, GitHub UV, and CNB UV URLs. The system proxy is not the cause of this incident.</p><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><ol><li>Add a process-lifetime, thread-safe libcurl initializer shared by probe and MirrorChyan HTTP code. Initialize it before starting concurrent probe tasks.</li><li>Keep successful probes first, ordered by latency. Retain failed probes afterward in their original order. A probe is advisory; only a real download or UV command may reject a source.</li><li>Log sanitized probe diagnostics: CURL result name/code and HTTP status only. Do not log proxy configuration, credentials, or response bodies.</li><li>Render every title/welcome/author line with its own horizontal centering decorator instead of centering the enclosing <code>vbox</code> as a single block.</li></ol><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to “Verification”">​</a></h2><ul><li>Unit test that failed probes remain available after successful probes and that an all-failed ranking preserves all candidates.</li><li>UV workflow test that all probe failures still lead to real source attempts.</li><li>TUI snapshot-coordinate test that title lines have the expected independent horizontal centers.</li><li>Build and run the full installer test suite, then copy the newly built Release executable into a brand-new disposable directory and complete a real end-to-end Windows installation. Verify <code>setup.toml</code>, the main checkout, OCR placement, the portable UV/Python environment, and BAAS startup; remove the disposable directory only after recording the result.</li></ul>',10)]))}const u=r(n,[["render",o]]);export{b as __pageData,u as default};
